import assert from 'node:assert/strict';
import {readFileSync,existsSync} from 'node:fs';
import {join} from 'node:path';
const root=new URL('../',import.meta.url).pathname;
const file=name=>readFileSync(join(root,'www',name),'utf8');
const auth=file('app-auth.js'),push=file('push-settings.js'),html=file('index.html'),diag=file('runtime-diagnostics.js');
assert.match(auth,/detectSessionInUrl:false/,'Native Auth must not parse URL sessions');
assert.match(auth,/persistSession:true,autoRefreshToken:true/,'Auth session should persist');
assert.match(auth,/auth\.signInWithPassword/,'Password sign-in must remain available');
assert.match(auth,/account_status/,'Account approvals must remain enforced');
assert.match(auth,/showPushWelcome\(uid\)\{\s*if\(window\.Capacitor/,'PWA onboarding must not open on native iOS');
assert.match(push,/supported=!nativeIOS&&/,'Native container must not register Web Push');
assert.match(push,/Native iOS-Push ist in dieser Testversion noch nicht eingerichtet/);
assert.match(html,/src="native-push.js"/);
assert.match(html,/src="runtime-diagnostics.js"/);
assert.match(diag,/popgoIOSDiagnostics/);
assert.match(file('diagnostics-ui.js'),/getSession\(\)/,'Native diagnostic panel must check current session read-only');
assert.match(html,/src="diagnostics-ui.js"/);
assert.ok(existsSync(join(root,'www','vorschlagen.html')),'Embedded form must ship');
assert.doesNotMatch(html,/\/pop-and-go\//,'Native app must not use GitHub Pages root');
console.log('iOS bundle static/auth compatibility checks passed.');
